from collections import defaultdict
from queue import Queue
from random import choice

NUM_REPLICAS = 3

class Signature:
    """Represents a signature for a key-value pair in a replica."""

    def __init__(self, storage_id, timestamp):
        self.storage_id = storage_id
        self.timestamp = timestamp

    def __eq__(self, other):
        return self.storage_id == other.storage_id and\
               self.timestamp == other.timestamp

    def __lt__(self, other):
        return self.timestamp < other.timestamp

class KeyValuePair:
    """Represents a key-value pair in a replica."""

    def __init__(self, key, value, signatures):
        self.key = key
        self.value = value
        self.signatures = signatures

    def __eq__(self, other):
        return self.key == other.key and self.value == other.value

class Replica:
    """Represents a single replica."""

    def __init__(self, storage_id, peers):
        self.storage_id = storage_id
        self.peers = peers
        self.storage = defaultdict(KeyValuePair)
        self.backup = defaultdict(KeyValuePair)
        self.sync_queue = Queue()

    def update(self, key, value):
        """Updates the value of 'key' to 'value', and then starts a sync operation."""

        self.storage[key] = KeyValuePair(key, value, set()
        for peer in self.peers:
            self.sync_queue.put((self.storage[key], peer, self.storage_id))
        self.sync()

    def get(self, key):
        return self.storage[key]

    def sync(self):
        """Syncs all changes from the sync queue."""

        while not self.sync_queue.empty():
            kvp, peer, storage_id = self.sync_queue.get()
            kvp.signatures.add(Signature(storage_id, kvp.signatures[len(kvp.signatures)-1].timestamp + 1))
            self.forward_sync(kvp, peer)

    def forward_sync(self, kvp, peer):
        """Forwards a sync operation to a peer."""
        next_peer = choice([p for p in self.peers if p != peer])
        self.sync_queue.put((kvp, next_peer, self.storage_id))
        self.sync()

